package in.tutorlink.config; import in.tutorlink.security.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.config.annotation.web.configuration.*; import org.springframework.security.config.http.*; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.*; import org.springframework.security.web.*; import org.springframework.security.web.authentication.*;
@Configuration @EnableWebSecurity public class SecurityConfig { final JwtFilter filter; public SecurityConfig(JwtFilter f){filter=f;} @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/h2-console/**").permitAll().requestMatchers(org.springframework.http.HttpMethod.GET,"/api/tutors/**","/api/tuition/**","/api/reviews/**").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).headers(x->x.frameOptions(f->f.sameOrigin())).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}}
